import "./style.css";
import { getWeathers } from "./utils/api";
import { capitalizedFirstCharacter, trimString } from "./utils/helper";
import createCurrentWeather from "./components/CurrentWeather";
import createErrorMessage from "./components/ErrorMessage";
import createLoading from "./components/Loading";
import createForecast from "./components/Forecast";

const form = document.getElementById("form");
const locationInput = document.getElementById("location");
const appContainer = document.getElementById("app");

let isMetric = true;

const resetLocationInput = () => {
  locationInput.value = "";
};

const clearAppContainer = () => {
  appContainer.innerHTML = "";
  resetLocationInput();
};

const updateWeatherInfo = async (e) => {
  let trimmedSearchTerm = "";

  if (e) {
    e.preventDefault();
    trimmedSearchTerm = trimString(locationInput.value);
  } else {
    trimmedSearchTerm = trimString("Samarinda");
  }

  const filteredSearchTerm = capitalizedFirstCharacter(trimmedSearchTerm);

  if (!filteredSearchTerm) {
    return;
  }

  // loading
  //
  const loading = createLoading();
  clearAppContainer();
  appContainer.append(loading);

  try {
    const weathersResult = await getWeathers(isMetric, filteredSearchTerm);

    const currentWeatherInfo = weathersResult.forecasts[0];
    const currentWeather = createCurrentWeather(isMetric, currentWeatherInfo);

    const currentForecast = createForecast(isMetric, weathersResult);

    clearAppContainer();

    appContainer.append(currentWeather, currentForecast);
  } catch (err) {
    if (err.message === "400") {
      const errorMessage = createErrorMessage({
        icon: "not_listed_location",
        message: `Location not found, are you sure ${filteredSearchTerm} is valid location?`,
      });

      clearAppContainer();

      appContainer.append(errorMessage);
    }
  }
};

form.addEventListener("submit", (e) => {
  updateWeatherInfo(e);
});

updateWeatherInfo();
